package com.fitbite.controller; import com.fitbite.dto.*; import com.fitbite.dto.RecommendationDtos.*; import com.fitbite.recommendation.RecommendationService; import jakarta.validation.Valid; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/recommendations") public class RecommendationController{private final RecommendationService service;public RecommendationController(RecommendationService service){this.service=service;}@GetMapping public ApiResponse<?> personalized(){return ApiResponse.ok("Personalized recommendations generated",service.personalized());}@PostMapping({"/ingredients"}) public ApiResponse<?> ingredients(@Valid @RequestBody IngredientRecommendationRequest r){return ApiResponse.ok("Ingredient recommendations generated",service.byIngredients(r.ingredients()));}@PostMapping public ApiResponse<?> generate(){return ApiResponse.ok("Personalized recommendations generated",service.personalized());}}
